const configObj = { debug: true, retries: 3 };
const configMap = new Map(Object.entries(configObj));
console.log(configMap.get("retries")); // 3

const backToObj = Object.fromEntries(configMap);
console.log(backToObj); // { debug: true, retries: 3 }

const jakiesSet = new Set(["a", "b", "c"]);

const tablicaA = Array.from(jakiesSet); // alternatywa dla [...jakiesSet]
const tablicaB = [...jakiesSet];

console.log(tablicaA); // ["a", "b", "c"]
console.log(tablicaB); // ["a", "b", "c"] - identyczny wynik

const liczbyZDuplikatami = [1, 2, 2, 3, 3, 3];
const unikalne = Array.from(new Set(liczbyZDuplikatami));
console.log(unikalne); // [1, 2, 3]

const mapa = new Map([[42, "wartosc"]]);
const obj = Object.fromEntries(mapa);

console.log(Object.keys(obj)); // ["42"] - STRING, nie liczba!
console.log(obj[42]); // "wartosc" - dziala, bo notacja [] konwertuje 42 na "42"

const mapa = new Map([[42, "wartosc"]]);
console.log(mapa.get(42)); // "wartosc" - typ klucza (liczba) ZACHOWANY
console.log([...mapa.keys()].every((k) => typeof k === "number")); // true

